from django.test import TestCase

from .models import Author, Book


class ReproTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        cls.author1 = Author.objects.create(name="Alice")
        cls.book1 = Book.objects.create(title="Poem by Alice", author=cls.author1)

    def test_multiple_filtered_relation_same_relation(self):
        qs = Author.objects.alias(
            book_alice=FilteredRelation(
                "book", condition=Q(book__title__icontains="alice")
            ),
            book_jane=FilteredRelation(
                "book", condition=Q(book__title__icontains="jane")
            ),
        ).filter(book_alice__isnull=False, book_jane__isnull=False)
        sql = str(qs.query)
        print("SQL:", sql)
        self.assertEqual(sql.count("JOIN"), 2)
